package com.lingyifan.lab;
import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import tools.jackson.databind.*;
import java.time.LocalDateTime; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @TestMethodOrder(MethodOrderer.OrderAnnotation.class) class LabManagerTests {
 @Autowired MockMvc mvc; @Autowired ObjectMapper json; static long equipmentId; static long reservationId; static long repairId;
 @Test @Order(1) void reservationBusinessLoop()throws Exception{String e=mvc.perform(post("/api/equipment").contentType(MediaType.APPLICATION_JSON).content("{\"assetCode\":\"OSC-001\",\"name\":\"数字示波器\",\"category\":\"电子测量\",\"labRoom\":\"A301\"}")).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();equipmentId=json.readTree(e).get("id").asLong();LocalDateTime start=LocalDateTime.now().plusDays(2),end=start.plusHours(2);String body="{\"equipmentId\":"+equipmentId+",\"studentId\":1001,\"startAt\":\""+start+"\",\"endAt\":\""+end+"\",\"purpose\":\"电路实验\"}";String r=mvc.perform(post("/api/reservations").contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();reservationId=json.readTree(r).get("id").asLong();mvc.perform(post("/api/reservations").contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isBadRequest());mvc.perform(patch("/api/reservations/"+reservationId+"/review").contentType(MediaType.APPLICATION_JSON).content("{\"decision\":\"APPROVED\",\"note\":\"安全培训已完成\"}")).andExpect(status().isOk());mvc.perform(post("/api/reservations/"+reservationId+"/checkout")).andExpect(jsonPath("$.status").value("IN_USE"));mvc.perform(post("/api/reservations/"+reservationId+"/return")).andExpect(jsonPath("$.status").value("COMPLETED"));}
 @Test @Order(2) void repairLoopAndValidation()throws Exception{String r=mvc.perform(post("/api/repairs").contentType(MediaType.APPLICATION_JSON).content("{\"equipmentId\":"+equipmentId+",\"reporterId\":1001,\"description\":\"探头接触不良\"}")).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();repairId=json.readTree(r).get("id").asLong();mvc.perform(patch("/api/repairs/"+repairId+"/resolve").contentType(MediaType.APPLICATION_JSON).content("{\"resolution\":\"更换探头并校准\"}")).andExpect(jsonPath("$.status").value("RESOLVED"));mvc.perform(post("/api/reservations").contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isBadRequest());mvc.perform(get("/api/dashboard")).andExpect(status().isOk()).andExpect(jsonPath("$.equipment").value(1));}
}
